package main

const pageHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YourMove Realize</title><script>try{let t=localStorage.getItem('theme');if(t)document.documentElement.dataset.theme=t}catch(e){}</script><style>
:root{color-scheme:light;--canvas:#F5F4F1;--surface:#fff;--ink:#242933;--muted:#606773;--border:#D9DDE3;--primary:#3459A5;--hover:#284984;--on:#fff;--alt:#f0f2f5} [data-theme=dark]{color-scheme:dark;--canvas:#191C22;--surface:#22262E;--ink:#EDF0F5;--muted:#AEB6C2;--border:#343A45;--primary:#AAC5FF;--hover:#C1D5FF;--on:#191C22;--alt:#2B3039}@media(prefers-color-scheme:dark){:root:not([data-theme]){color-scheme:dark;--canvas:#191C22;--surface:#22262E;--ink:#EDF0F5;--muted:#AEB6C2;--border:#343A45;--primary:#AAC5FF;--hover:#C1D5FF;--on:#191C22;--alt:#2B3039}}
*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:16px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{max-width:1200px;margin:auto;padding:30px 40px;display:flex;justify-content:space-between;align-items:center}.brand{font-size:18px;font-weight:750;letter-spacing:-.04em}.brand span{font-weight:400;color:var(--muted);margin-left:6px}main{max-width:1120px;margin:0 auto;padding:65px 40px 110px}.hero{display:grid;grid-template-columns:1.1fr .9fr;gap:90px;align-items:center;min-height:480px}.eyebrow{color:var(--primary);font-size:11px;letter-spacing:.19em;font-weight:750;text-transform:uppercase}h1{font:normal clamp(43px,5.8vw,72px)/1.06 Georgia,serif;letter-spacing:-.045em;margin:20px 0 26px;max-width:800px}h2{font:normal clamp(28px,3.5vw,42px)/1.15 Georgia,serif;letter-spacing:-.03em;margin:12px 0 22px}h3{font-size:17px;margin:0 0 8px}p{margin:0 0 18px}.lede{font-size:19px;color:var(--muted);max-width:570px;line-height:1.65}.muted,small{color:var(--muted)}small{font-size:13px}.card{background:var(--surface);border:1px solid var(--border);border-radius:5px;padding:32px;box-shadow:0 18px 54px rgba(29,39,58,.045)}.drop{border:1px dashed var(--primary);padding:42px 24px;text-align:center}.drop.drag{background:var(--alt)}button,.button{display:inline-block;background:var(--primary);color:var(--on);border:1px solid var(--primary);border-radius:3px;padding:13px 22px;font:inherit;font-weight:650;cursor:pointer;text-decoration:none}button:hover,.button:hover{background:var(--hover);border-color:var(--hover)}button.secondary,.button.secondary{background:transparent;color:var(--ink);border-color:var(--border)}button.link{background:none;border:0;color:var(--primary);padding:4px 0;text-decoration:underline;font-weight:600}.theme{background:none;color:var(--ink);border:1px solid var(--border);padding:7px 12px;font-size:13px}.theme:hover{background:var(--alt);border-color:var(--border)}:focus-visible{outline:3px solid var(--primary);outline-offset:3px}.stack{max-width:790px}.preview{white-space:pre-wrap;max-height:300px;overflow:auto;font:14px/1.6 ui-monospace,monospace;background:var(--alt);padding:20px}.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-top:25px}.notice{border-left:3px solid var(--primary);background:var(--surface);padding:16px 20px;margin-bottom:24px}.leads{display:grid;gap:12px}.lead{width:100%;text-align:left;background:var(--surface);color:var(--ink);border:1px solid var(--border);padding:22px 24px;font-weight:400}.lead:hover{background:var(--alt);border-color:var(--primary)}.lead strong{display:block;font-size:18px;margin-bottom:5px}.lead span{color:var(--muted)}.history{border-left:1px solid var(--border);padding-left:24px;margin:30px 0;color:var(--muted)}.history p{white-space:pre-wrap}.question{font:normal clamp(25px,3vw,36px)/1.25 Georgia,serif;margin:18px 0 24px}textarea,input[type=text]{width:100%;background:var(--surface);color:var(--ink);border:1px solid var(--border);border-radius:3px;padding:14px;font:inherit}textarea{resize:vertical;min-height:150px}label{font-weight:650;display:block;margin:20px 0 8px}.reveal{border-top:1px solid var(--border);padding-top:30px;margin-top:35px}.reveal-grid{display:grid;grid-template-columns:1fr 1fr;gap:35px}.quote{font:italic 22px/1.55 Georgia,serif;white-space:pre-wrap}details{margin:24px 0}summary{cursor:pointer;color:var(--primary);font-weight:650}blockquote{margin:18px 0;padding:20px;border-left:2px solid var(--primary);background:var(--alt);white-space:pre-wrap}.ending{font:italic 25px/1.4 Georgia,serif;margin-top:45px}.waiting{display:none;color:var(--muted);margin-top:15px}.busy .waiting{display:block}.busy button[type=submit]{opacity:.6;pointer-events:none}footer{border-top:1px solid var(--border);padding:24px 40px;color:var(--muted);font-size:13px;text-align:center}@media(max-width:700px){header{padding:22px}main{padding:40px 22px 75px}.hero{grid-template-columns:1fr;gap:35px;min-height:0}.card{padding:24px}.reveal-grid{grid-template-columns:1fr;gap:15px}h1{font-size:44px}.actions button,.actions .button{width:100%;text-align:center}}
</style></head><body><header><div class="brand">YourMove <span>/ Realize</span></div><button class="theme" id="theme" type="button" aria-label="Toggle light and dark theme">◐ &nbsp; Theme</button></header><main>
{{if .Notice}}<div class="notice" role="alert">{{.Notice}}</div>{{end}}
{{if eq .Stage "welcome"}}<div class="hero"><section><div class="eyebrow">A little more to your story</div><h1>There's more to your story.</h1><p class="lede">Your résumé tells people where you've worked. Realize helps uncover the strengths, decisions, and experiences hiding between the lines.</p><p class="muted">Your experience stays yours. You decide what to keep.</p></section><section class="card"><form action="/upload" method="post" enctype="multipart/form-data" id="upload"><div class="drop" id="drop"><h3>Start with your résumé</h3><p class="muted">Drop a PDF or Word résumé here, or choose a file.</p><label for="file" class="button" style="display:inline-block;cursor:pointer">Choose a résumé</label><input id="file" name="resume" type="file" accept=".pdf,.docx" required style="max-width:100%;margin-top:15px"><div class="actions" style="justify-content:center"><button type="submit">Upload and preview</button></div></div><p><small>Master or role-specific résumé · PDF or DOCX · up to 10 MiB</small></p></form></section></div>
{{else if eq .Stage "preview"}}<div class="stack"><div class="eyebrow">Your résumé</div><h1>Let's see what's already here.</h1><p class="lede">A quick check before we begin. This is the text we extracted from <strong>{{.Filename}}</strong>.</p>{{if .Truncated}}<div class="notice">This document exceeds the engine’s 8,000-byte limit. Only the beginning shown here will be sent and considered; the full extracted text remains in this session.</div>{{end}}<div class="preview">{{.State.Resume.Text}}</div><p style="margin-top:24px">Realize extracts text locally. By beginning discovery, you authorize relevant résumé text and your subsequent answers to be sent to Baseten for AI inference.</p><form action="/begin" method="post" class="infer"><div class="actions"><button type="submit">Begin discovery →</button></div><p class="waiting" role="status">Finding experiences worth exploring…</p></form><form action="/reset" method="post"><button class="link" type="submit">Choose another résumé</button></form></div>
{{else if eq .Stage "leads"}}<div class="stack"><div class="eyebrow">Choose a starting point</div><h1>Start with something worth exploring.</h1><p class="lede">These are possibilities in your résumé. Choose the one you’d like to talk about.</p><div class="leads">{{range .State.Leads}}<form action="/select" method="post" class="infer"><button class="lead" name="lead" value="{{.ID}}" type="submit"><strong>{{.Title}} →</strong><span>{{.Why}}</span></button><p class="waiting" role="status">Preparing your question…</p></form>{{end}}</div></div>
{{else if eq .Stage "conversation"}}<div class="stack"><div class="eyebrow">A conversation with Realize</div><h2>A few questions can reveal what a bullet point leaves out.</h2>{{if .State.SelectedLead}}<p class="muted">Exploring: {{.State.SelectedLead.Title}}</p>{{end}}{{if .State.Responses}}<div class="history">{{range .State.Responses}}<small>REALIZE</small><p>{{.Question}}</p><small>YOU</small><p>{{.Source.Text}}</p>{{end}}</div>{{end}}{{if .State.Proposal}}<div class="card"><div class="eyebrow">A discovery is ready</div><h3>There may be more here than your résumé shows.</h3><p class="muted">You can review a source-linked suggestion now, or keep exploring below.</p><form method="post" action="/reveal"><button type="submit">See your realization →</button></form></div>{{else if .State.Responses}}<p class="muted">There isn't enough source-supported detail for a suggestion yet. Continue if you can add more, or retry if a request failed.</p>{{end}}{{if .State.Question}}{{if lt (len .State.Responses) 6}}<div class="reveal"><div class="eyebrow">Realize asks</div><p class="question">{{.State.Question}}</p><form action="/answer" method="post" class="infer"><label for="answer">Your response</label><textarea id="answer" name="answer" maxlength="2000" required placeholder="Take your time. What happened?"></textarea><div class="actions"><button type="submit">Continue →</button></div><p class="waiting" role="status">Thinking through what you shared…</p></form></div>{{else}}<p class="notice">You've reached the end of this conversation. If there is no proposal, there wasn't enough supported detail to create one.</p>{{end}}{{else}}<form action="/retry" method="post" class="infer"><div class="actions"><button type="submit">Try again</button></div><p class="waiting" role="status">Thinking through what you shared…</p></form>{{end}}</div>
{{else if eq .Stage "reveal"}}<div class="stack"><div class="eyebrow">Your experience, in focus</div><h1>You were doing more than your résumé said.</h1><p class="lede">{{.State.Proposal.Title}}</p><div class="reveal reveal-grid"><section><div class="eyebrow">What you did</div><p class="question">{{.State.Proposal.Experience}}</p></section><section><div class="eyebrow">What this reveals</div><p>{{.State.Proposal.Claim}}</p><div class="eyebrow">Why it matters</div><p>This interpretation may help you describe the value of your contribution in your own words. Check that it feels accurate to you.</p></section></div><div class="reveal"><div class="eyebrow">What remains unknown</div>{{if .State.Proposal.Unresolved}}<ul>{{range .State.Proposal.Unresolved}}<li>{{.}}</li>{{end}}</ul>{{else}}<p class="muted">No additional limitations were identified; review the wording for anything missing.</p>{{end}}<details><summary>See where this came from</summary><blockquote>{{.State.Proposal.Quote}}</blockquote><small>Exact quote from {{.State.Proposal.SourceID}} · Your account, not independent verification.</small></details><div class="actions"><form method="post" action="/review"><button type="submit">Review Career Evidence →</button></form><form method="post" action="/continue"><button class="secondary" type="submit">Continue exploring</button></form></div></div></div>
{{else if eq .Stage "review"}}<div class="stack"><div class="eyebrow">Your words, your decision</div><h1>Make it yours.</h1><p class="lede">Review and correct this suggestion. Keeping it means you have reviewed it, not that it has been independently verified.</p><form method="post" action="/keep"><label for="title">Title</label><input id="title" name="title" type="text" maxlength="160" value="{{.State.Proposal.Title}}" required><label for="experience">What you did</label><textarea id="experience" name="experience" maxlength="1500" required>{{.State.Proposal.Experience}}</textarea><label for="claim">What this suggests</label><textarea id="claim" name="claim" maxlength="1500" required>{{.State.Proposal.Claim}}</textarea><div class="reveal"><div class="eyebrow">What remains unknown</div>{{if .State.Proposal.Unresolved}}<ul>{{range .State.Proposal.Unresolved}}<li>{{.}}</li>{{end}}</ul>{{else}}<p>None identified by the model.</p>{{end}}<details open><summary>Original supporting statement</summary>{{range .State.Responses}}{{if eq .Source.ID $.State.Proposal.SourceID}}<blockquote>{{.Source.Text}}</blockquote>{{end}}{{end}}<small>Referenced quote: “{{.State.Proposal.Quote}}” · {{.State.Proposal.SourceID}}. This source stays unchanged when you edit the wording.</small></details></div><div class="actions"><button type="submit">Keep as Career Evidence</button></div></form><form method="post" action="/reject"><button class="link" type="submit">Reject this suggestion</button></form></div>
{{else if eq .Stage "saved"}}<div class="stack"><div class="eyebrow">Candidate-reviewed Career Evidence</div><h1>The experience was already yours.</h1><p class="lede">Now you can see it more clearly.</p><div class="card"><h2>{{.Saved.Title}}</h2><div class="eyebrow">What you did</div><p>{{.Saved.Experience}}</p><div class="eyebrow">What this suggests</div><p>{{.Saved.Claim}}</p><div class="eyebrow">What remains unknown</div>{{if .Saved.Unresolved}}<ul>{{range .Saved.Unresolved}}<li>{{.}}</li>{{end}}</ul>{{else}}<p>None identified.</p>{{end}}<details><summary>See your original statement</summary><blockquote>{{.Saved.SourceText}}</blockquote><small>Source: {{.Saved.SourceID}} · Quote: “{{.Saved.Quote}}”</small></details></div><p style="margin-top:22px" class="muted">This record is candidate-reviewed, not independently verified. It remains here only while this server is running. Download the JSON to keep it.</p><div class="actions"><a class="button" href="/download">Download Career Evidence JSON</a></div><form method="post" action="/reset"><button class="link" type="submit">Start over</button></form></div>{{end}}
</main><footer>YourMove Realize · Your experience belongs to you.</footer><script>
document.getElementById('theme').addEventListener('click',()=>{let d=document.documentElement;let current=d.dataset.theme|| (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');d.dataset.theme=current==='dark'?'light':'dark';try{localStorage.setItem('theme',d.dataset.theme)}catch(e){}});document.querySelectorAll('form.infer').forEach(f=>f.addEventListener('submit',()=>{f.classList.add('busy')}));let drop=document.getElementById('drop'),file=document.getElementById('file');if(drop){['dragenter','dragover'].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(n=>drop.addEventListener(n,e=>{e.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>{file.files=e.dataTransfer.files})}
</script></body></html>`
